enum Event: Codable, Hashable, Sendable {
    case goal(EventGoal)
    case caution(EventCaution)
    case secondCaution(EventSecondCaution)
    case sendOff(EventSendOff)
    case sinBin(EventSinBin)
    case secondSinBin(EventSecondSinBin)
    case stoppage(EventStoppage)
    case periodEnd(EventPeriodEnd)
    case penaltyKick(EventPenaltyKick)
    case injury(EventInjury)
    case suspension(EventSuspension)
    case clockAdjusted(EventClockAdjusted)
    case abandonment(EventAbandonment)
    /// One of a kind this app doesn't know yet (from a newer server), its JSON kept.
    case unknown(JSONValue)

    var type: String {
        switch self {
        case .goal: return "goal"
        case .caution: return "caution"
        case .secondCaution: return "secondCaution"
        case .sendOff: return "sendOff"
        case .sinBin: return "sinBin"
        case .secondSinBin: return "secondSinBin"
        case .stoppage: return "stoppage"
        case .periodEnd: return "periodEnd"
        case .penaltyKick: return "penaltyKick"
        case .injury: return "injury"
        case .suspension: return "suspension"
        case .clockAdjusted: return "clockAdjusted"
        case .abandonment: return "abandonment"
        case .unknown(let value): return value["type"]?.string ?? ""
        }
    }

    init(from decoder: Decoder) throws {
        let keys = try decoder.container(keyedBy: JSONKey.self)
        switch try? keys.decode(String.self, forKey: JSONKey("type")) {
        case "goal": self = .goal(try EventGoal(from: decoder))
        case "caution": self = .caution(try EventCaution(from: decoder))
        case "secondCaution": self = .secondCaution(try EventSecondCaution(from: decoder))
        case "sendOff": self = .sendOff(try EventSendOff(from: decoder))
        case "sinBin": self = .sinBin(try EventSinBin(from: decoder))
        case "secondSinBin": self = .secondSinBin(try EventSecondSinBin(from: decoder))
        case "stoppage": self = .stoppage(try EventStoppage(from: decoder))
        case "periodEnd": self = .periodEnd(try EventPeriodEnd(from: decoder))
        case "penaltyKick": self = .penaltyKick(try EventPenaltyKick(from: decoder))
        case "injury": self = .injury(try EventInjury(from: decoder))
        case "suspension": self = .suspension(try EventSuspension(from: decoder))
        case "clockAdjusted": self = .clockAdjusted(try EventClockAdjusted(from: decoder))
        case "abandonment": self = .abandonment(try EventAbandonment(from: decoder))
        default: self = .unknown(try JSONValue(from: decoder))
        }
    }

    func encode(to encoder: Encoder) throws {
        switch self {
        case .goal(let value): try value.encode(to: encoder)
        case .caution(let value): try value.encode(to: encoder)
        case .secondCaution(let value): try value.encode(to: encoder)
        case .sendOff(let value): try value.encode(to: encoder)
        case .sinBin(let value): try value.encode(to: encoder)
        case .secondSinBin(let value): try value.encode(to: encoder)
        case .stoppage(let value): try value.encode(to: encoder)
        case .periodEnd(let value): try value.encode(to: encoder)
        case .penaltyKick(let value): try value.encode(to: encoder)
        case .injury(let value): try value.encode(to: encoder)
        case .suspension(let value): try value.encode(to: encoder)
        case .clockAdjusted(let value): try value.encode(to: encoder)
        case .abandonment(let value): try value.encode(to: encoder)
        case .unknown(let value): try value.encode(to: encoder)
        }
    }
}

