    /// The name of the account made with it.
    var usedBy: String? = nil
    /// When it was emailed, if it was.
    var emailedAt: Timestamp? = nil
    /// The plan the account joins (PLAN-5); the default (or the sign-up trial) when there's none.
    var plan: PlanName? = nil
    /// For how many days, then the default plan; none: it doesn't end.
    var planDays: Int? = nil
}

