    var home: Team
    var away: Team
    var gender: String? = nil
    /// Free text, as leagues write it: U12, U19, Adult, O35.
    var ageGroup: String? = nil
    var competitionId: Id? = nil
    var venueId: Id? = nil
    /// One of the venue's pitches.
    var pitchId: Id? = nil
    /// The user's role in this match.
    var role: String? = nil
    /// The other officials.
    var crew: [CrewMember]
    var notes: String? = nil
    /// What to expect: competitive, one-sided, team strengths and so on.
    var outlook: String? = nil
    var fee: Fee? = nil
    var external: ExternalRef? = nil
    /// Who assigned the match (SET-15): a name, typed in or set by an integration or import.
    var assignor: String? = nil
    var tags: Tags? = nil
    /// The pitch's corners as marked on the watch for this match (TRK-13).
