/// How a match is played: periods, breaks, extra time, penalties and what the watch records.
struct MatchFormat: Codable, Hashable, Sendable {
    /// Periods of normal time: 1 (SET-16, a tournament game of one period) to 4.
    var periods: Int
    var periodSec: Int
    /// Between periods, and before and between extra-time periods.
    var breakSec: Int
    /// A break halfway through each period of normal time (TMR-7).
    var halfwayBreak: Bool
    var halfwayBreakSec: Int
    var teamSize: Int
    /// No longer chosen per match: the account's match screen sets it (TMR-11). Kept for older apps.
    var clock: String
    var trackStoppage: Bool
    /// The clock (TMR-15): true stops the match clock while play is stopped (a stoppage, the halfway break), as US high school (NFHS) and college (NCAA) games keep time, with no added time; it needs trackStoppage. Missing means it runs on, as the Laws have it.
    var stoppingClock: Bool? = nil
    /// With a stopping clock, recording a goal or a card stops it, until Start/Stop at the restart (TMR-15). Missing means on.
    var stopForGoalsCards: Bool? = nil
    /// With stoppage tracked, the halfway break's time is added on as stoppage (TMR-12). Missing means on: formats saved before the setting.
    var breakStoppage: Bool? = nil
    /// Ask the scorer's number for each goal (EVT-10). Missing means on: formats saved before this always asked.
    var goalScorers: Bool? = nil
    /// Ask the goal type (goal, DFK, penalty, own goal) for each goal (EVT-8).
    var goalTypes: Bool
    var extraTime: Bool
    var extraTimePeriods: Int
    var extraTimePeriodSec: Int
    /// With extra time, a goal in it ends the match, the scoring team winning (ET-6). Missing means off.
    var goldenGoal: Bool? = nil
    var penalties: Bool
    /// Temporary dismissals (EVT-12): Sin bin in the watch's team menu, a countdown with the match clock. Missing means off.
    var sinBins: Bool? = nil
    /// A sin bin's length (EVT-12). Missing means 10 minutes.
    var sinBinSec: Int? = nil
}

