/// What happened in a match, as recorded on a watch, or entered or corrected afterward (RES).
struct MatchRecord: Codable, Hashable, Sendable {
    var id: Id
    /// Raised by the server on every change; clients send the version they last saw so conflicts can be spotted.
    var version: Int
    var updatedAt: Timestamp
    /// Set when the record is deleted; deleted records are kept so other devices learn of the deletion.
    var deletedAt: Timestamp? = nil
    /// The planned match; absent for a quick match started on the watch, for which the server makes a match.
    var matchId: Id? = nil
    /// What recorded it: the watch app and the watch, for example garmin:006-B3703-00 (a Garmin part number), wearos:SM-R860 (the model) or applewatch:Watch7,3 (the hardware identifier; applewatch:Apple Watch from apps before it).
    var device: String? = nil
    var outcome: String
    var periods: [PeriodPlayed]
    var score: MatchRecordScore
    /// Shoot-out score, when there was one.
    var penalties: MatchRecordPenalties? = nil
    /// The match ended on a golden goal in extra time (ET-6): the team that scored it won.
    var goldenGoal: Bool? = nil
    /// The match was played on a clock that stops (TMR-15), as US high school and college games are: events' times are the clock's, its stoppages are when it stood still, and there was no added time, so the added-time stats leave the match out (STAT-9).
    var stoppingClock: Bool? = nil
    /// Distance the referee covered during the match, in meters, from the watch's GPS.
    var distanceM: Double? = nil
    /// Which way the first period's kickoff team attacked, when the referee recorded it on the watch (PRE-8); heatmaps use it (TRK-9).
    var kickoffDirection: MatchRecordKickoffDirection? = nil
    var events: [Event]
    /// How the recording went (DIAG-1).
    var diagnostics: MatchDiagnostics? = nil
    /// When its result was last corrected after the match (RES-1); set by the server whenever the outcome, score, shoot-out, golden goal or events change. A watch's later upload of the same match then changes nothing (RES-4).
    var editedAt: Timestamp? = nil
    /// The result exactly as the watch first sent it, kept by the server the first time it's corrected (RES-3), so it can be shown or put back. Absent for results entered without a watch.
    var original: RecordedResult? = nil
}

