struct OffenderTeamOfficial: Codable, Hashable, Sendable {
    var kind: String = "teamOfficial"
    var role: String
    var name: String? = nil
}

enum Offender: Codable, Hashable, Sendable {
    case player(OffenderPlayer)
    case teamOfficial(OffenderTeamOfficial)
    /// One of a kind this app doesn't know yet (from a newer server), its JSON kept.
    case unknown(JSONValue)

    var kind: String {
        switch self {
        case .player: return "player"
        case .teamOfficial: return "teamOfficial"
        case .unknown(let value): return value["kind"]?.string ?? ""
        }
    }

    init(from decoder: Decoder) throws {
        let keys = try decoder.container(keyedBy: JSONKey.self)
        switch try? keys.decode(String.self, forKey: JSONKey("kind")) {
        case "player": self = .player(try OffenderPlayer(from: decoder))
        case "teamOfficial": self = .teamOfficial(try OffenderTeamOfficial(from: decoder))
        default: self = .unknown(try JSONValue(from: decoder))
        }
    }

    func encode(to encoder: Encoder) throws {
        switch self {
        case .player(let value): try value.encode(to: encoder)
        case .teamOfficial(let value): try value.encode(to: encoder)
        case .unknown(let value): try value.encode(to: encoder)
        }
    }
}

