struct Referee: Codable, Hashable, Sendable {
    var id: Id
    /// Raised by the server on every change; clients send the version they last saw so conflicts can be spotted.
    var version: Int
    var updatedAt: Timestamp
    /// Set when the record is deleted; deleted records are kept so other devices learn of the deletion.
    var deletedAt: Timestamp? = nil
    var name: String
    /// What the officials line on match cards calls them (WEB-20); without it, their surname as guessed from the name.
    var shortName: String? = nil
    /// Other names they go by, such as the ones merged into this referee (DUP-3); imports and searches find the referee by them.
    var aliases: [String]? = nil
    var email: String? = nil
    var phone: String? = nil
    var notes: String? = nil
    var tags: Tags? = nil
    /// Referees the user said aren't the same person, so they aren't suggested as duplicates again (DUP-5).
    var distinctFrom: [Id]? = nil
}

/// A Referee as a client sends it to save it: the server sets updatedAt and deletedAt, and version only goes with an update.
struct RefereeInput: Codable, Hashable, Sendable {
    var name: String
    /// What the officials line on match cards calls them (WEB-20); without it, their surname as guessed from the name.
    var shortName: String? = nil
    /// Other names they go by, such as the ones merged into this referee (DUP-3); imports and searches find the referee by them.
    var aliases: [String]? = nil
    var email: String? = nil
    var phone: String? = nil
    var notes: String? = nil
    var tags: Tags? = nil
    /// Referees the user said aren't the same person, so they aren't suggested as duplicates again (DUP-5).
    var distinctFrom: [Id]? = nil
    /// The id from the URL; can be left out.
    var id: Id? = nil
    /// The version last seen, when updating. Leave it out to create the record.
    var version: Int? = nil
}

/// Referees to merge into one (DUP-3, DUP-4).
struct RefereeMerge: Codable, Hashable, Sendable {
    /// The referees to merge into this one; they're deleted.
    var from: [Id]
    /// The name to keep: one of the referees' names or other names. The rest become other names.
    var name: String
    /// When they have different emails, the one to keep; otherwise the one there is.
    var email: String? = nil
    /// When they have different phone numbers, the one to keep; otherwise the one there is.
    var phone: String? = nil
}

/// A referee merge as chosen so far, to preview (DUP-4).
struct RefereeMergeDraft: Codable, Hashable, Sendable {
    /// The referees to merge into this one; they're deleted.
    var from: [Id]
    /// The name chosen so far; left out, or not one of theirs, the kept referee's.
    var name: String? = nil
    /// The email chosen so far, where they differ.
    var email: String? = nil
    /// The phone number chosen so far, where they differ.
    var phone: String? = nil
}

/// What merging these referees would make (DUP-4, DUP-11).
struct RefereeMergePreview: Codable, Hashable, Sendable {
    /// The referee kept, then the others, in the order sent; each with its reasons when it's among the likeliest.
    var referees: [DuplicateMember]
    /// Every name to choose from: theirs and their other names, once each. The rest become other names.
    var names: [String]
    /// The name that will be kept.
    var name: String
    /// Their emails, once each: a choice when there's more than one.
    var emails: [String]
    var email: String? = nil
    /// Their phone numbers, once each: a choice when there's more than one.
    var phones: [String]
    var phone: String? = nil
    /// Their matches as one referee, crew typed in under one of their names included; a match counts once.
    var together: MatchCount
    /// What to send to POST /v1/referees/{id}/merge to merge exactly this.
    var merge: RefereeMerge
}

struct RefereeMergeResult: Codable, Hashable, Sendable {
    /// The referee they were merged into, as saved.
    var referee: Referee
    /// How many referees were merged into it (and deleted).
    var merged: Int
    /// Matches whose crew now names it, including crew typed as one of its names.
    var matchesUpdated: Int
}

