    var mapsApp: String? = nil
    /// Beats a minute, for heart-rate zones (TRK-4).
    var maxHeartRate: Int? = nil
    /// Where sprinting starts, in km/h, for the speed bands and sprints (TRK-11); the other bands scale with it. 21 when not set.
    var sprintKph: Double? = nil
    /// Minutes before kickoff the calendar feed's events start, for travel and warming up (CAL-3); 0 starts them at kickoff. 30 when not set.
    var calendarArriveMin: Int? = nil
    /// Before several reminders (CAL-3): minutes before kickoff for the calendar feed's one reminder; 0 for none. Used only when none of calendarReminders, calendarDayBefore and calendarDayOf is set; 60 when nothing is.
    var calendarReminderMin: Int? = nil
    /// The calendar feed's reminders, in minutes before kickoff (CAL-3): 15-minute steps up to 3 hours.
    var calendarReminders: [Int]? = nil
    /// A reminder the day before a match at this time (HH:MM, in the match's time zone); none when not set.
    var calendarDayBefore: String? = nil
    /// Missing until it's first chosen: watches then keep two clocks stacked (time left over match time) with the time of day and names, or their own choice.
    var watchScreen: WatchScreen? = nil
    /// For Garmin and Apple watches (INP-10); upDown when not set. Wear OS watches always swipe sideways, as a swipe down from the top opens their quick settings.
    var teamSwipes: String? = nil
    /// A reminder on the day of a match at this time (HH:MM, in the match's time zone), when that's before the event starts; none when not set.
    var calendarDayOf: String? = nil
    /// The match list's next match folded to a single strip (WEB-27); open when not set.
    var nextMatchCollapsed: Bool? = nil
    /// The role a new match starts with on the match forms (SET-17); referee when not set. An import, an integration or a quick match from the watch keeps its own.
    var usualRole: String? = nil
    /// The format a new match starts with on the match forms (SET-17): the last one saved on a form, or chosen in Settings. Not set until then: forms start from defaultFormat (2×45), offering the starter formats. A competition's template still wins.
    var usualFormat: UsualFormat? = nil
    /// Get ready on Matches (WEB-32), the same on the website and the phones: what the person chose there, so it follows them to another browser or phone.
    var getReady: UserSettingsGetReady? = nil
}

