/// A pitch's corners walked on the watch (TRK-13, SYNC-12).
struct WatchPitchMarking: Codable, Hashable, Sendable {
    /// A planned match's id.
    var matchId: Id? = nil
    /// Or, for a quick match, when it was started on the watch (it has no id until it's uploaded).
    var created: Int? = nil
    /// [latitude, longitude] in millionths of a degree, as the watch's tracks are: its JSON keeps only six significant figures of a decimal.
    var corners: [JSONValue]
    /// When they were marked, in seconds since 1970.
    var at: Int
}

/// How the watch's running screen looks, for all the account's watches (UI-21, UI-24).
struct WatchScreen: Codable, Hashable, Sendable {
    /// For older watch builds: the nearest old layout, kept in step with the fields below.
    var layout: String
    /// What the second clock shows (UI-22); down is the time left. Never the same as mainClock.
    var secondClock: String
    /// Missing in setups saved before the four choices (UI-21): worked out from layout.
    var clocks: String? = nil
    /// How the match clock counts (TMR-11); up (Match time) when missing.
    var mainClock: String? = nil
    /// How the break clock counts (TMR-4); down when missing.
    var breakClock: String? = nil
    /// Missing in older setups: worked out from layout.
    var edge: String? = nil
    /// The team names over the clock, or false for scores only. Missing in older setups: worked out from layout.
    var names: Bool? = nil
    /// When it was last changed, wherever that was: the latest change wins (UI-24).
    var changedAt: Timestamp
}

/// The match screen as chosen on the watch, or as it's sent to one (UI-21, UI-24); the latest change wins.
struct WatchScreenChange: Codable, Hashable, Sendable {
    /// The nearest old layout. A watch that sends only this and secondClock is a build from before the four choices (UI-21).
    var layout: String
    var secondClock: String
    var clocks: String? = nil
    var mainClock: String? = nil
    var breakClock: String? = nil
    var edge: String? = nil
    var names: Bool? = nil
    /// When it was changed on the watch, in seconds since 1970.
    var at: Int
}

/// Part of a match's track as the watch recorded it (TRK-7): GPS and heart rate about once a second during the periods.
struct WatchTrackChunk: Codable, Hashable, Sendable {
    /// The match's created time, as in its upload: which match the track is for.
    var created: Int
    /// When the track starts (the first kickoff), in seconds since 1970.
    var start: Int
    /// Which chunk this is, from 0.
    var index: Int
    /// How many chunks the track has.
    var count: Int
    /// The watch model, "venu2".
    var device: String? = nil
    /// The chunk's samples as the watch packs them, "dt,dlat,dlon,speed,hr;" each: tenths of a second since the sample before (empty for 10; the chunk's first counts from start), millionths of a degree moved since the chunk's position before (the first is whole; both empty without a new fix), the speed the watch measured in cm/s, and beats a minute. Empty fields mean unknown; trailing ones are left off.
    var data: String
}

struct WatchTrackResult: Codable, Hashable, Sendable {
    /// How many of the track's chunks the server has.
    var received: Int
    var count: Int
    /// waiting: for more chunks or the match; saved: the track is on the match report; kept: the match report already had a track (from a file, say), which stays; dropped: nothing in it could be used (no positions or heart rate).
    var track: String
}

/// The cards' reasons chosen on the watch (EVT-14); a code that isn't the scheme's for that card is left out.
struct WatchUploadMisconduct: Codable, Hashable, Sendable {
    /// The codes the watch listed.
    var scheme: SchemeId
    /// [the card's index in events, its code].
    var codes: [JSONValue]
}

/// How the recording went, for tracing problems (DIAG-1).
struct WatchUploadDiagnostics: Codable, Hashable, Sendable {
    /// [period from 0, 0 kickoff or 1 its end, percent].
    var battery: [JSONValue]? = nil
    var app: String? = nil
    var firmware: String? = nil
    /// Seconds from kickoff to the first GPS fix.
    var gpsFirstFixSec: Int? = nil
    /// Track samples taken.
    var gpsSamples: Int? = nil
    /// Of those, how many had no GPS fix.
    var gpsMissed: Int? = nil
    /// How many times the app started again mid-match (R-5).
    var restarts: Int? = nil
}

/// A finished match as the watch saved it. The server stores it as a match record.
struct WatchUpload: Codable, Hashable, Sendable {
    /// When the match was started on the watch, in seconds since 1970.
    var created: Int
    /// The planned match it was started from; none for a quick match.
    var matchId: Id? = nil
    /// The watch model, "venu2".
    var device: String? = nil
    var home: String
    var away: String
    var homeName: String? = nil
    var awayName: String? = nil
    var homeColor: Int? = nil
    var awayColor: Int? = nil
    var numPeriods: Int
    var periodSec: Int
    var halftimeSec: Int
    var teamSize: Int? = nil
    /// When the halfway break comes, or -1 for none.
    var breakAtSec: Int? = nil
    var breakLenSec: Int? = nil
    var extraTime: Bool? = nil
    var etPeriods: Int? = nil
    var etPeriodSec: Int? = nil
    /// The format's golden goal (ET-6).
    var goldenGoal: Bool? = nil
    var penalties: Bool? = nil
    var clockStyle: Int? = nil
    var trackStoppage: Bool? = nil
    /// The format's stopping clock (TMR-15): every event's seconds are the clock's, which stood still during stoppages (S).
    var stoppingClock: Bool? = nil
    var stopForGoalsCards: Bool? = nil
    var breakStoppage: Bool? = nil
    var goalScorers: Bool? = nil
    var goalTypes: Bool? = nil
    /// The format's sin bins (EVT-12).
    var sinBins: Bool? = nil
    var sinBinSec: Int? = nil
    /// [home, away].
    var score: JSONValue
    /// Shoot-out score, [home, away].
    var pens: JSONValue? = nil
    /// It ended on a golden goal in extra time (ET-6).
    var golden: Bool? = nil
    /// How far the referee ran, in meters.
    var distanceM: Double? = nil
    /// When each period kicked off, in seconds since 1970, for the track's figures (TRK-3).
    var startedAt: [Int]? = nil
    /// The team that kicked off the first period: 0 home, 1 away, -1 not chosen.
    var kickoff: Int? = nil
    /// The compass heading of the goal the home team attacked in the first period, in radians from true north, when the referee recorded it (PRE-8).
    var homeHeading: Double? = nil
    var events: [WatchEvent]
    /// The cards' reasons chosen on the watch (EVT-14); a code that isn't the scheme's for that card is left out.
    var misconduct: WatchUploadMisconduct? = nil
    /// How the recording went, for tracing problems (DIAG-1).
    var diagnostics: WatchUploadDiagnostics? = nil
}

struct WatchUploadResult: Codable, Hashable, Sendable {
    /// The match record. The same every time this match is sent, so sending it again updates it.
    var recordId: Id
    /// The planned match, or the one made for a quick match.
    var matchId: Id
}

/// What the sky is doing, for the icon: the most significant condition while the match is played.
enum WeatherCondition {
    static let clear = "clear"
    static let partlyCloudy = "partlyCloudy"
    static let cloudy = "cloudy"
    static let fog = "fog"
    static let drizzle = "drizzle"
    static let rain = "rain"
    static let snow = "snow"
    static let storm = "storm"
    static let all = [clear, partlyCloudy, cloudy, fog, drizzle, rain, snow, storm]
}

struct WeatherHour: Codable, Hashable, Sendable {
    /// The start of the hour.
    var time: Timestamp
    var condition: String
    var isDay: Bool
    var temperatureC: Double
    /// Rain (or melted snow) during the hour.
    var precipitationMm: Double
    var precipitationChance: Double? = nil
}

/// Something in the forecast that could stop or cancel the match (WX-4). Rough rules, not a prediction.
struct WeatherRisk: Codable, Hashable, Sendable {
    var kind: String
    /// possible: worth watching; likely: the match may well be called off or stopped.
    var level: String
    /// What the level is based on: millimeters of rain (wetField: in the 24 hours before; rain: during the match), centimeters of snow, or the highest feels-like temperature in °C (heat).
    var amount: Double? = nil
}

/// wetField: rain in the 24 hours before (fields close); rain, storm, snow: during the match or the hour before; heat: feels-like temperature while playing.
enum WeatherRiskKind {
    static let wetField = "wetField"
    static let rain = "rain"
    static let storm = "storm"
    static let snow = "snow"
    static let heat = "heat"
    static let all = [wetField, rain, storm, snow, heat]
}

/// The latest delivery and how it went.
struct WebhookLastDelivery: Codable, Hashable, Sendable {
    var at: Timestamp
    var status: String
    var responseCode: Int? = nil
}

/// A URL that hears about changes to the account's records (HOOK-1).
struct Webhook: Codable, Hashable, Sendable {
    var id: Id
    /// Where deliveries are POSTed.
    var url: String
    /// Which records' changes it hears about.
    var topics: [String]
    /// Paused webhooks get no deliveries.
    var active: Bool
    var createdAt: Timestamp
    /// The latest delivery and how it went.
    var lastDelivery: WebhookLastDelivery? = nil
}

/// One change sent to a webhook, with how it went.
struct WebhookDelivery: Codable, Hashable, Sendable {
    /// Also sent as X-LawFive-Delivery.
    var id: Id
    /// match.created, matchRecord.updated, venue.deleted…
    var event: String
    /// pending: waiting for its next try; failed: gave up after five tries.
    var status: String
    var attempts: Int
    var responseCode: Int? = nil
    /// Why the last try failed, when it didn't get an answer.
    var error: String? = nil
    /// Sent with Send test.
    var test: Bool
    var createdAt: Timestamp
    var deliveredAt: Timestamp? = nil
}

struct WebhookInput: Codable, Hashable, Sendable {
    /// http or https.
    var url: String
    var topics: [String]
    /// true when left out.
    var active: Bool? = nil
}

/// What each delivery POSTs, as JSON. It's signed: X-LawFive-Signature is t=<unix seconds>,v1=<hex HMAC-SHA256 of "<t>.<body>" with the webhook's secret>.
struct WebhookPayload: Codable, Hashable, Sendable {
    /// The delivery's id; the same on every retry, so a receiver can ignore one it has had.
    var id: Id
    /// <topic>.<created|updated|deleted>
    var event: String
    /// When the change was made.
    var createdAt: Timestamp
    /// true for Send test; data is then an example.
    var test: Bool? = nil
    /// The record as stored (as GET returns it); for deleted, its id, version and deletedAt.
    var data: [String: JSONValue]
}

/// The kinds of record a webhook can hear about: matches, match reports (results), venues, referees, competitions and match templates.
enum WebhookTopic {
    static let match = "match"
    static let matchRecord = "matchRecord"
    static let venue = "venue"
    static let referee = "referee"
    static let competition = "competition"
    static let matchTemplate = "matchTemplate"
    static let all = [match, matchRecord, venue, referee, competition, matchTemplate]
}
